/**
 * Daily Verse API — GET /api/daily
 *
 * Returns today's verse (deterministic by UTC day-of-year) plus a one-sentence
 * reflection question generated by Claude Haiku.
 *
 * The reflection is cached per-verse-id for 24 hours in a module-level Map.
 * Vercel Fluid Compute reuses instances, so cache hits are common — we don't
 * want to hit the LLM on every request when the verse only changes once a day.
 *
 * Response is also CDN-cached for an hour (with SWR for a day) so even cold
 * function instances see most traffic served from the edge.
 */
import { generateText } from 'ai';
import { anthropic } from '@ai-sdk/anthropic';
import { getDailyVerse } from '@/lib/daily-verse';
import { clientKey, rateLimit, rateLimitResponse } from '@/lib/rate-limit';

export const maxDuration = 15;

// 60 requests in a burst, refilling 10/min (= 1/6 per second) sustained.
const DAILY_LIMIT = { capacity: 60, refillRatePerSec: 10 / 60 };

const TTL_MS = 24 * 60 * 60 * 1000;

interface ReflectionCacheEntry {
  question: string;
  expires: number;
}

// Module-level cache survives across requests on the same function instance.
const reflectionCache = new Map<string, ReflectionCacheEntry>();

const SYSTEM_PROMPT =
  'You are jAIsus. Given a scripture verse, write ONE warm reflection question someone could sit with today. Maximum 20 words. No preamble, no quotes, just the question.';

export async function GET(req: Request) {
  const rl = rateLimit(`daily:${clientKey(req)}`, DAILY_LIMIT);
  if (!rl.ok) return rateLimitResponse(rl);

  const verse = getDailyVerse();

  let reflection = '';
  let cached = false;

  const now = Date.now();
  const hit = reflectionCache.get(verse.id);
  if (hit && hit.expires > now) {
    reflection = hit.question;
    cached = true;
  } else {
    try {
      const { text } = await generateText({
        model: anthropic('claude-haiku-4-5-20251001'),
        system: SYSTEM_PROMPT,
        prompt: `${verse.text} — ${verse.reference}`,
        maxOutputTokens: 60,
      });
      reflection = text.trim();
      if (reflection) {
        reflectionCache.set(verse.id, {
          question: reflection,
          expires: now + TTL_MS,
        });
      }
    } catch {
      // Swallow LLM errors — still return the verse so the client can render.
      reflection = '';
      cached = false;
    }
  }

  return new Response(
    JSON.stringify({
      verse: {
        id: verse.id,
        text: verse.text,
        reference: verse.reference,
        theme: verse.theme,
      },
      reflection,
      cached,
    }),
    {
      headers: {
        'Content-Type': 'application/json',
        'Cache-Control':
          'public, max-age=3600, s-maxage=3600, stale-while-revalidate=86400',
      },
    }
  );
}
